// pure, easy to test
export function shippingCost(subtotalCents: number): number {
  if (subtotalCents < 0) throw new RangeError('negative subtotal');
  return subtotalCents >= 5000 ? 0 : 499;
}

it.each([
  [0, 499], [4999, 499], [5000, 0], [12000, 0],
])('subtotal %i -> shipping %i', (subtotal, expected) => {
  expect(shippingCost(subtotal)).toBe(expected);
});

it('rejects negatives', () => {
  expect(() => shippingCost(-1)).toThrow(RangeError);
});

