import { renderHook, act } from '@testing-library/react';
import { useCounter } from './useCounter';

it('increments and resets', () => {
  const { result } = renderHook(() => useCounter(5));

  act(() => result.current.increment());
  expect(result.current.count).toBe(6);

  act(() => result.current.reset());
  expect(result.current.count).toBe(5);
});

it('reacts to new initial values', () => {
  const { result, rerender } = renderHook(({ start }) => useCounter(start), {
    initialProps: { start: 1 },
  });
  rerender({ start: 10 });
  // assert the documented behavior for changed props
});

function createWrapper() {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  return ({ children }: { children: React.ReactNode }) => (
    <QueryClientProvider client={client}>{children}</QueryClientProvider>
  );
}

it('fetches the user', async () => {
